//! Lowering: turning an owner value into the value generated bindings expect.
//!
//! The two sides never name each other's types. The owner side, generated by
//! `#[derive(WitType)]`, takes a value apart into *wire parts* in declaration
//! order with every representation rule applied. The binding side, generated
//! by `#[derive(FromParts)]` on the bindings, builds a value from parts by
//! position. Both follow the same reflected order, so a field can only meet
//! its counterpart.
//!
//! Records are a field list `Fields((a, (b, ())))` and enums a nested choice
//! `Cases(Either::Next(Either::This(payload)))`. Nesting instead of tuples of
//! every length means neither side has an arity limit.

/// An owner value that can be taken apart into wire parts.
///
/// Derived together with [`WitType`](crate::WitType), from the same fields and
/// rules, so the parts always have the shape the generated WIT declares.
pub trait Lower {
    /// The value's wire parts. They contain no binding types.
    type Parts;

    /// Take the value apart, applying its representation rules.
    fn lower(self) -> Self::Parts;
}

/// A binding value that can be built from the wire parts `Parts`.
///
/// Derived on generated bindings through wit-bindgen's `additional_derives`.
#[diagnostic::on_unimplemented(
    message = "`{Self}` cannot be assembled from the wire parts `{Parts}`",
    label = "the binding type and the owner type disagree here",
    note = "they differ in field order, count or type; regenerate the WIT and forwarding file \
            from the schema, then rebuild"
)]
pub trait FromParts<Parts>: Sized {
    /// Build the value from parts in declaration order.
    fn from_parts(parts: Parts) -> Self;
}

/// The fields of a record, as a nested pair list ending in `()`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Fields<List>(pub List);

/// The selected case of a variant or enum, as a nested [`Either`].
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Cases<Choice>(pub Choice);

/// One step of a nested choice: this case, or one of the following.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Either<This, Next> {
    /// The case at this position, with its payload parts.
    This(This),
    /// A later case.
    Next(Next),
}

/// The end of a nested choice. It has no value: every case came before it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Never {}

/// Lower `source` and assemble the binding value from its parts.
///
/// Generated forwarding calls this once per result. Going through one function
/// with explicit bounds makes the compiler name the exact field whose
/// conversion is missing, instead of only the outermost binding type.
pub fn assemble<Source, Binding>(source: Source) -> Binding
where
    Source: Lower,
    Binding: FromParts<Source::Parts>,
{
    let parts = source.lower();
    Binding::from_parts(parts)
}

macro_rules! leaf {
    ($($ty:ty),* $(,)?) => {
        $(
            impl Lower for $ty {
                type Parts = $ty;

                fn lower(self) -> $ty {
                    self
                }
            }

            impl FromParts<$ty> for $ty {
                fn from_parts(parts: $ty) -> $ty {
                    parts
                }
            }
        )*
    };
}

// `()` is the part of a unit case and of a unit `Result` side.
leaf!(
    bool,
    u8,
    u16,
    u32,
    u64,
    i8,
    i16,
    i32,
    i64,
    f32,
    f64,
    char,
    String,
    ()
);

impl<T: Lower> Lower for Vec<T> {
    type Parts = Vec<T::Parts>;

    fn lower(self) -> Self::Parts {
        self.into_iter().map(Lower::lower).collect()
    }
}

impl<Parts, Binding: FromParts<Parts>> FromParts<Vec<Parts>> for Vec<Binding> {
    fn from_parts(parts: Vec<Parts>) -> Self {
        parts.into_iter().map(Binding::from_parts).collect()
    }
}

impl<T: Lower> Lower for Option<T> {
    type Parts = Option<T::Parts>;

    fn lower(self) -> Self::Parts {
        self.map(Lower::lower)
    }
}

impl<Parts, Binding: FromParts<Parts>> FromParts<Option<Parts>> for Option<Binding> {
    fn from_parts(parts: Option<Parts>) -> Self {
        parts.map(Binding::from_parts)
    }
}

impl<T: Lower, E: Lower> Lower for Result<T, E> {
    type Parts = Result<T::Parts, E::Parts>;

    fn lower(self) -> Self::Parts {
        self.map(Lower::lower).map_err(Lower::lower)
    }
}

impl<OkParts, ErrParts, Okay, Failed> FromParts<Result<OkParts, ErrParts>> for Result<Okay, Failed>
where
    Okay: FromParts<OkParts>,
    Failed: FromParts<ErrParts>,
{
    fn from_parts(parts: Result<OkParts, ErrParts>) -> Self {
        parts.map(Okay::from_parts).map_err(Failed::from_parts)
    }
}

/// Owned indirection does not change the value's parts.
impl<T: Lower> Lower for Box<T> {
    type Parts = T::Parts;

    fn lower(self) -> Self::Parts {
        let value = *self;
        value.lower()
    }
}

macro_rules! tuple {
    ($(($element:ident, $parts:ident, $binding:ident)),+) => {
        impl<$($element: Lower),+> Lower for ($($element,)+) {
            type Parts = ($($element::Parts,)+);

            fn lower(self) -> Self::Parts {
                #[allow(non_snake_case, reason = "bindings are named after their type parameters")]
                let ($($element,)+) = self;
                ($($element.lower(),)+)
            }
        }

        impl<$($parts, $binding: FromParts<$parts>),+> FromParts<($($parts,)+)> for ($($binding,)+) {
            fn from_parts(parts: ($($parts,)+)) -> Self {
                #[allow(non_snake_case, reason = "bindings are named after their type parameters")]
                let ($($parts,)+) = parts;
                ($($binding::from_parts($parts),)+)
            }
        }
    };
}

tuple!((A, PA, BA));
tuple!((A, PA, BA), (B, PB, BB));
tuple!((A, PA, BA), (B, PB, BB), (C, PC, BC));
tuple!((A, PA, BA), (B, PB, BB), (C, PC, BC), (D, PD, BD));
tuple!(
    (A, PA, BA),
    (B, PB, BB),
    (C, PC, BC),
    (D, PD, BD),
    (E, PE, BE)
);
tuple!(
    (A, PA, BA),
    (B, PB, BB),
    (C, PC, BC),
    (D, PD, BD),
    (E, PE, BE),
    (F, PF, BF)
);
tuple!(
    (A, PA, BA),
    (B, PB, BB),
    (C, PC, BC),
    (D, PD, BD),
    (E, PE, BE),
    (F, PF, BF),
    (G, PG, BG)
);
tuple!(
    (A, PA, BA),
    (B, PB, BB),
    (C, PC, BC),
    (D, PD, BD),
    (E, PE, BE),
    (F, PF, BF),
    (G, PG, BG),
    (H, PH, BH)
);
